for (const item of $input.all()) {
  const formDate = $input.first().json.Date
  const time = {
    tirggerAt: $input.first().json.timestamp,
    submittedAt: formDate,
    date: new Date(),
  }

  time.date = new Date(time.tirggerAt || time.submittedAt)
  const dateTime = DateTime.fromJSDate(time.date)

  item.json = {
    createdAt: dateTime.toFormat('yyyy-MM-dd hh:mm:ss'),
    slug:  dateTime.toFormat('yyyy-MM-dd'),
    time
  }
}

return $input.all();

const articles = items.map(item => {
  const content = item.json.output;

  const titleMatch = content.match(/title:\s*(.*?)\\n/i);
  const descMatch = content.match(/description:\s*(.*?)\\n/i);

  const title = titleMatch ? titleMatch[1].trim() : '今日资讯速览';
  const digest = descMatch ? descMatch[1].trim() : '';

  // 提取第一张图片
  const imgRegex = /<img[^>]+src="(.*?)"[^>]*>/g;
  let match;
  let firstValidImg = '';
  while ((match = imgRegex.exec(content)) !== null) {
    const url = match[1];
    if (!url.includes('cdn-telegram')) {
      firstValidImg = match[0];
      break;
    }
  }

  let cleanedContent = content.replace(imgRegex, '');
  if (firstValidImg) {
    cleanedContent = firstValidImg + '\n' + cleanedContent;
  }

  return {
    title,
    author: 'AI日报',
    digest,
    show_cover_pic: 1,
    content: cleanedContent,
    content_source_url: 'https://example.com',
    thumb_media_id: 'xxx', // 注意：要动态填入上传图片返回的 media_id
  };
});

return [{ json: { articles } }];
